import{_ as o,a0 as p,w as d,s as r,ao as n,I as l,x as i,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"SSH 密钥管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"SSH 密钥管理工具 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"SSH 密钥管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"SSH 密钥管理工具 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200220 Tools for SSH key management","title":"SSH 密钥管理工具","tag":"202003","desc":""},"relativePath":"202003/20200220 Tools for SSH key management.md","filePath":"[post].md"}'),h={name:"202003/20200220 Tools for SSH key management.md"};function g(k,s,u,b,m,c){const t=p("Link");return d(),r("div",null,[s[20]||(s[20]=n('<h1 id="ssh-密钥管理工具" tabindex="-1">SSH 密钥管理工具 <a class="header-anchor" href="#ssh-密钥管理工具" aria-label="Permalink to “SSH 密钥管理工具”">​</a></h1><blockquote><p>常用开源工具的省时快捷方式。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/01/122336zyldgpse6eyrbymt.jpg" alt=""></p><p>我经常使用 SSH。我发现自己每天都要登录多个服务器和树莓派（与我位于同一房间，并接入互联网）。我有许多设备需要访问，并且获得访问权限的要求也不同，因此，除了使用各种 <code>ssh</code> / <code>scp</code> 命令选项之外，我还必须维护一个包含所有连接详细信息的配置文件。</p><p>随着时间的推移，我发现了一些省时的技巧和工具，你可能也会发现它们有用。</p><h3 id="ssh-密钥" tabindex="-1">SSH 密钥 <a class="header-anchor" href="#ssh-密钥" aria-label="Permalink to “SSH 密钥”">​</a></h3><p>SSH 密钥是一种在不使用密码的情况下认证 SSH 连接的方法，可以用来加快访问速度或作为一种安全措施（如果你关闭了密码访问权限并确保仅允许授权的密钥）。要创建 SSH 密钥，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-keygen</span></span></code></pre></div><p>这将在 <code>~/.ssh/</code> 中创建一个密钥对（公钥和私钥）。将私钥（<code>id_rsa</code>）保留在 PC 上，切勿共享。你可以与其他人共享公钥（<code>id_rsa.pub</code>）或将其放置在其他服务器上。</p><h3 id="ssh-copy-id" tabindex="-1">ssh-copy-id <a class="header-anchor" href="#ssh-copy-id" aria-label="Permalink to “ssh-copy-id”">​</a></h3><p>如果我在家中或公司工作时使用树莓派，则倾向于将 SSH 设置保留为默认设置，因为我不担心内部信任网络上的安全性，并且通常将 SSH 密钥（公钥）复制到树莓派上，以避免每次都使用密码进行身份验证。为此，我使用 <code>ssh-copy-id</code> 命令将其复制到树莓派。这会自动将你的密钥（公钥）添加到树莓派：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-copy-id pi@192.168.1.20</span></span></code></pre></div><p>在生产服务器上，我倾向于关闭密码身份验证，仅允许授权的 SSH 密钥登录。</p><h3 id="ssh-import-id" tabindex="-1">ssh-import-id <a class="header-anchor" href="#ssh-import-id" aria-label="Permalink to “ssh-import-id”">​</a></h3><p>另一个类似的工具是 <code>ssh-import-id</code>。你可以使用此方法通过从 GitHub 导入密钥来授予你自己（或其他人）对计算机或服务器的访问权限。例如，我已经在我的 GitHub 帐户中注册了各个 SSH 密钥，因此无需密码即可推送到 GitHub。这些公钥是有效的，因此 <code>ssh-import-id</code> 可以使用它们在我的任何计算机上授权我：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-import-id gh:bennuttall</span></span></code></pre></div><p>我还可以使用它来授予其他人访问服务器的权限，而无需询问他们的密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh-import-id gh:waveform80</span></span></code></pre></div><h3 id="storm" tabindex="-1">storm <a class="header-anchor" href="#storm" aria-label="Permalink to “storm”">​</a></h3><p>我还使用了名为 Storm 的工具，该工具可帮助你将 SSH 连接添加到 SSH 配置中，因此你不必记住这些连接细节信息。你可以使用 <code>pip</code> 安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip3 install stormssh</span></span></code></pre></div><p>然后，你可以使用以下命令将 SSH 连接信息添加到配置中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ storm add pi3 pi@192.168.1.20</span></span></code></pre></div><p>然后，你可以只使用 <code>ssh pi3</code> 来获得访问权限。类似的还有 <code>scp file.txt pi3:</code> 或 <code>sshfs pi pi3:</code>。</p><p>你还可以使用更多的 SSH 选项，例如端口号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ storm add pi3 pi@192.168.1.20:2000</span></span></code></pre></div>',26)),l("p",null,[s[1]||(s[1]=i("你可以参考 Storm 的",-1)),e(t,{href:"https://stormssh.readthedocs.io/en/stable/usage.html"},{default:a(()=>[...s[0]||(s[0]=[i("文档",-1)])]),_:1}),s[2]||(s[2]=i("轻松列出、搜索和编辑已保存的连接。Storm 实际所做的只是管理 SSH 配置文件 ",-1)),s[3]||(s[3]=l("code",null,"~/.ssh/config",-1)),s[4]||(s[4]=i(" 中的项目。一旦了解了它们是如何存储的，你就可以选择手动编辑它们。配置中的示例连接如下所示：",-1))]),s[21]||(s[21]=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host pi3</span></span>
<span class="line"><span>   user pi</span></span>
<span class="line"><span>   hostname 192.168.1.20</span></span>
<span class="line"><span>   port 22</span></span></code></pre></div><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>从树莓派到大型的云基础设施，SSH 是系统管理的重要工具。熟悉密钥管理会很方便。你还有其他 SSH 技巧要添加吗？我希望你在评论中分享他们。</p><hr>`,4)),l("p",null,[s[6]||(s[6]=i("via: ",-1)),e(t,{href:"https://opensource.com/article/20/2/ssh-tools"},{default:a(()=>[...s[5]||(s[5]=[i("https://opensource.com/article/20/2/ssh-tools",-1)])]),_:1})]),l("p",null,[s[11]||(s[11]=i("作者：",-1)),e(t,{href:"https://opensource.com/users/bennuttall"},{default:a(()=>[...s[7]||(s[7]=[i("Ben Nuttall",-1)])]),_:1}),s[12]||(s[12]=i(" 选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[8]||(s[8]=[i("lujun9972",-1)])]),_:1}),s[13]||(s[13]=i(" 译者：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1}),s[14]||(s[14]=i(" 校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[17]||(s[17]=i("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[15]||(s[15]=[i("LCTT",-1)])]),_:1}),s[18]||(s[18]=i(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:a(()=>[...s[16]||(s[16]=[i("Linux中国",-1)])]),_:1}),s[19]||(s[19]=i(" 荣誉推出",-1))])])}const C=o(h,[["render",g]]);export{y as __pageData,C as default};
